private void planUpsert(List<AlgoPerfRow> rows,
                        Map<String, Long> existMap,
                        List<AlgoPerfRow> toUpdate,
                        List<AlgoPerfRow> toInsert) {
    for (AlgoPerfRow row : rows) {
        // 业务键：(算法标识, 芯片类型, 分辨率)。命中就更新，不命中才插
        String key = row.getAlgoId() + "|" + row.getChipType() + "|" + row.getResolution();
        Long existId = existMap.get(key);
        if (existId != null) {
            row.setId(existId);
            toUpdate.add(row);
        } else {
            toInsert.add(row);
            // 同一批里先插的那条要立刻占住 key，避免批内重复插
            existMap.put(key, DUPLICATE_MARK);
        }
    }
}

