public void sync(List<String> algoIds) {
    // 几百个算法按 10 个一批，批内并发、批间串行
    for (List<String> batch : Lists.partition(algoIds, BATCH_SIZE_10)) {
        List<CompletableFuture<Void>> futures = new ArrayList<>(batch.size());
        for (String algoId : batch) {
            futures.add(CompletableFuture.runAsync(() -> {
                try {
                    AlgoPerfRaw raw = powerCardClient.getPowerCard(algoId);
                    List<AlgoPerfRow> rows = AlgoMappingUtils.toRows(raw);
                    saveRows(rows);
                } catch (Exception e) {
                    log.warn("sync algo perf failed, algoId: {}", algoId, e);
                }
            }, POOL));
        }
        CompletableFuture.allOf(futures.toArray(new CompletableFuture[0])).join();
    }
}
